def _template_synthetic_dataset(config: dict, seed: int = 42):
    """R4 synthetic stand-in (only used when allow_synthetic_data=True).
    input (1, 96, 96) (float); target kind 'segmentation'.
    Evidence: explicit:monai(in_channels,spatial)=(1, 96, 96); classes:monai.out_channels=1"""
    input_shape = tuple(config.get("synthetic_input_shape", (1, 96, 96)))
    n = int(config.get("synthetic_num_samples", 256))
    g = torch.Generator().manual_seed(seed)
    x = torch.randn((n, *input_shape), generator=g)
    y = (torch.rand((n, 1, *input_shape[1:]), generator=g) > 0.5).float()
    return torch.utils.data.TensorDataset(x, y)

